def model(p):
    n1,n2,n3,n4=p[0],p[1],p[2],p[3]
    X=np.column_stack([A**n1, t*A**n2, t**2*A**n3, np.ones_like(A), t, t**2, t**3, A**n4*t**2])
    return X
def res(p):
